 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                colors.setdefault(color, []).append((r, c))
    objects = []
    for color, cells in colors.items():
        min_r = min(r for r, c in cells)
        max_r = max(r for r, c in cells)
        min_c = min(c for r, c in cells)
        max_c = max(c for r, c in cells)
        shape = [(r - min_r, c - min_c) for r, c in cells]
        objects.append((min_c, color, max_r - min_r + 1, max_c - min_c + 1, shape))
    objects.sort(key=lambda obj: obj[0])

    out = [[0] * w for _ in range(h)]
    origin_r = origin_c = 0
    prev_h = prev_w = None
    for i, (_, color, oh, ow, shape) in enumerate(objects):
        if i:
            origin_r += prev_h - 1
            origin_c += prev_w - 1
        for dr, dc in shape:
            r, c = origin_r + dr, origin_c + dc
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color
        prev_h, prev_w = oh, ow
    return out
